"""認証情報の設定ファイルを管理するモジュール。

環境変数、プロジェクト設定ファイル、ユーザー設定ファイルの優先順位
（環境変数 > プロジェクト設定 > ユーザー設定）で設定値を解決する。
"""

import os
from pathlib import Path

CONFIG_FILENAME = ".wpctl_conf"
CONFIG_KEYS = ("WP_SITE_URL", "WP_USER", "WP_APP_PASSWORD")


def project_config_path() -> Path:
    """プロジェクト単位の設定ファイルパスを返す（カレントディレクトリ直下）。"""
    return Path.cwd() / CONFIG_FILENAME


def user_config_path() -> Path:
    """ユーザー単位の設定ファイルパスを返す（ホームディレクトリ直下）。"""
    return Path.home() / CONFIG_FILENAME


def _read_config_file(path: Path) -> dict[str, str]:
    """KEY=VALUE 形式の設定ファイルを読み込む。

    Args:
        path: 設定ファイルのパス

    Returns:
        設定値の辞書（ファイルが存在しない場合は空辞書）
    """
    if not path.is_file():
        return {}
    values: dict[str, str] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        if key in CONFIG_KEYS:
            values[key] = value.strip()
    return values


def _write_config_file(path: Path, values: dict[str, str]) -> None:
    """KEY=VALUE 形式で設定ファイルへ書き込む（既存の値とマージする）。

    Args:
        path: 設定ファイルのパス
        values: 追加・更新する設定値
    """
    merged = _read_config_file(path)
    merged.update({k: v for k, v in values.items() if v})
    lines = [f"{key}={merged[key]}" for key in CONFIG_KEYS if key in merged]
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    path.chmod(0o600)


def _ensure_gitignore_entry(base_dir: Path) -> None:
    """プロジェクト単位の設定ファイルが Git 管理対象外になるよう .gitignore を整備する。

    Args:
        base_dir: 設定ファイルの配置ディレクトリ
    """
    gitignore_path = base_dir / ".gitignore"
    if gitignore_path.is_file():
        content = gitignore_path.read_text(encoding="utf-8")
        if CONFIG_FILENAME in content.splitlines():
            return
        prefix = content if content.endswith("\n") or not content else content + "\n"
        gitignore_path.write_text(prefix + f"{CONFIG_FILENAME}\n", encoding="utf-8")
    else:
        gitignore_path.write_text(f"{CONFIG_FILENAME}\n", encoding="utf-8")


def resolve(key: str) -> tuple[str | None, str]:
    """設定値を優先順位（環境変数 > プロジェクト設定 > ユーザー設定）で解決する。

    Args:
        key: 設定キー（CONFIG_KEYS のいずれか）

    Returns:
        (値, 参照元) のタプル。参照元は "env" / "project" / "user" / "none"
    """
    env_value = os.environ.get(key)
    if env_value:
        return env_value, "env"
    project_value = _read_config_file(project_config_path()).get(key)
    if project_value:
        return project_value, "project"
    user_value = _read_config_file(user_config_path()).get(key)
    if user_value:
        return user_value, "user"
    return None, "none"


def resolve_all() -> dict[str, tuple[str | None, str]]:
    """全設定キーを解決する。

    Returns:
        設定キーごとの (値, 参照元) を持つ辞書
    """
    return {key: resolve(key) for key in CONFIG_KEYS}


def get_missing_keys() -> list[str]:
    """未設定の設定キー一覧を返す。

    Returns:
        値が解決できなかった設定キーのリスト
    """
    return [key for key, (value, _) in resolve_all().items() if not value]


def get_credentials() -> dict[str, str]:
    """WordPress API 呼び出しに必要な認証情報を解決する。

    Returns:
        設定キーと値の辞書

    Raises:
        KeyError: いずれかの設定値が未設定の場合
    """
    credentials: dict[str, str] = {}
    for key, (value, _) in resolve_all().items():
        if not value:
            raise KeyError(key)
        credentials[key] = value
    return credentials


def set_config(values: dict[str, str], scope: str = "project") -> Path:
    """認証情報を設定ファイルへ保存する。

    Args:
        values: 保存する設定値（キーは CONFIG_KEYS のいずれか）
        scope: 保存先（"project" または "user"）

    Returns:
        保存先の設定ファイルパス

    Raises:
        ValueError: scope が不正な場合
    """
    if scope == "project":
        path = project_config_path()
        _write_config_file(path, values)
        _ensure_gitignore_entry(path.parent)
    elif scope == "user":
        path = user_config_path()
        _write_config_file(path, values)
    else:
        raise ValueError(f"不正な scope です: {scope}")
    return path
